UPDATE member2 SET email = #{email}, birth = TO_DATE(#{birth}, 'YYYY-MM-DD'), 
	profile_photo = #{profile_photo, jdbcType=VARCHAR}, tel = #{tel}, zip = #{zip}, addr1 = #{addr1}, 
	addr2 = #{addr2}, gender = #{gender}, pref_position = #{pref_position}
WHERE memberIdx = #{memberIdx}
